import { test, expect } from '@playwright/test';

test.describe('Form Submission and Data Invalidation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com/form');
  });

  test('should submit the form successfully', async ({ page }) => {
    await page.getByLabel('Name').fill('John Doe');
    await page.getByLabel('Email').fill('john.doe@example.com');
    await page.getByRole('button', { name: 'Submit' }).click();

    const successMessage = await page.getByText('Form submitted successfully!');
    await expect(successMessage).toBeVisible();
  });

  test('should invalidate stale data after form submission', async ({ page }) => {
    await page.getByLabel('Name').fill('Jane Doe');
    await page.getByLabel('Email').fill('jane.doe@example.com');
    await page.getByRole('button', { name: 'Submit' }).click();

    const staleDataMessage = await page.getByText('Stale data invalidated.');
    await expect(staleDataMessage).toBeVisible();
  });
});
